  if (before) { await closeRoamDialogs(page); return { before, after: true, dialogButton: null }; }
  await box.click();
  await sleep(page, 1200);
  const buttons = await page.locator(".bp3-dialog .bp3-dialog-footer button").allInnerTexts();
  const pick = buttons.find((b) => /Reactivate without Migration/.test(b)) || buttons.find((b) => /Activate and Migrate/.test(b));
  if (!pick) return { before, after: null, dialogButton: null, buttons };
  await page.locator(".bp3-dialog .bp3-dialog-footer button", { hasText: pick }).first().click();
