  while (Date.now() - start < 180000) {
    if (await box.locator("input").isChecked().catch(() => false)) break;
    await sleep(page, 500);
  }
  await sleep(page, 1500);
  const after = await box.locator("input").isChecked();
  await closeRoamDialogs(page);
  return { before, after, dialogButton: pick, buttons };
};

