    if (!p) { await window.roamAlphaAPI.data.page.create({ page: { title } }); p = window.roamAlphaAPI.q(`[:find ?u . :in $ ?t :where [?p :node/title ?t] [?p :block/uid ?u]]`, title); }
    const uid = window.roamAlphaAPI.util.generateUID();
    await window.roamAlphaAPI.data.block.create({ location: { "parent-uid": p, order: "last" }, block: { uid, string: uid, props: { "discourse-graph": d } } });
    return uid;
  }, { sourceUid, destinationUid, hasSchema });

export const storedRelationsFor = (page, uids) =>
  page.evaluate(async (uids) => {
    const rows = await window.roamAlphaAPI.data.async.q(`[:find ?u ?d :where [?s :block/uid ?u] [?s :block/props ?p] [(get ?p :discourse-graph) ?d]]`);
    const g = (o, k) => o?.[`:${k}`] ?? o?.[k];
    return rows.map(([u, d]) => ({ uid: u, sourceUid: g(d, "sourceUid"), destinationUid: g(d, "destinationUid"), hasSchema: g(d, "hasSchema") }))
      .filter((r) => uids.includes(r.sourceUid) || uids.includes(r.destinationUid));
  }, uids);

