        const uid = window.roamAlphaAPI.util.generateUID();
        await window.roamAlphaAPI.data.block.create({ location: { "parent-uid": parent, order: i }, block: { uid, string: list[i].text, ...(list[i].open === false ? { open: false } : {}) } });
        if (list[i].children?.length) await make(uid, list[i].children);
      }
    };
    await make(parentUid, nodes);
    return true;
  }, { parentUid, nodes });

