// ENG-1955 fixture seed. Run with the MAIN build only (uid-typed arrows are created natively, cloud rooms are pre-migration).
import fs from "node:fs";
import path from "node:path";
import {
  installEditorFinder, closeRoamDialogs, openPage, uidOf, readState, writeState, writeDump, sleep, waitEditor,
  readCanvasProps, writeCanvasProps, summarizeRecords, editorRecords, readPersonalFlags, enableStoredRelationsUI,
  readConfig, createPage, createStoredRelation, storedRelationsFor, createTree, clearChildren, switchToCloud, cloudIcon,
  allLogs, errorsIn, SEED_DIR,
} from "./lib.mjs";
import { ROLE, FIXTURES, nodeGroups, canvasTitle, nodeLabel, nodeTitle } from "./fixtures.mjs";
import { buildHub, HUB_TITLE } from "./hub.mjs";

const SEQ = "com.roam-research.discourse-graphs";
const DR = "discourse-relation";
const clone = (x) => JSON.parse(JSON.stringify(x));
const rid = (p) => `${p}:${Math.random().toString(36).slice(2, 12)}${Math.random().toString(36).slice(2, 8)}`;

const qb = (props) => props["roamjs-query-builder"];
const store = (props) => qb(props)?.tldraw?.store;

export default {
  async ready({ page }) {
    await closeRoamDialogs(page);
    return page.evaluate(() => Boolean(window.roamAlphaAPI && window.roamjs?.extension?.queryBuilder));
  },
  async run({ page, outDir }) {
    const logs = allLogs(page);
    await installEditorFinder(page);
    const out = { steps: {} };
    const flush = () => fs.writeFileSync(path.join(outDir, "seed-result.json"), JSON.stringify(out, null, 2));
    const step = async (name, fn) => {
      try { out.steps[name] = (await fn()) ?? "ok"; } catch (e) { out.steps[name] = { error: String(e?.stack || e).slice(0, 800) }; flush(); throw e; }
      flush();
      return out.steps[name];
    };

    // ---- config ----
    const config = await step("config", () => readConfig(page));
    const typeId = Object.fromEntries(["Claim", "Evidence", "Question", "Source"].map((t) => [t, config.nodes.find((n) => n.text === t)?.type]));
    const R = {};
    for (const [k, r] of Object.entries(ROLE)) {
      const hit = config.rels.find((x) => x.label === r.label && x.source === typeId[r.source] && x.destination === typeId[r.destination]);
      if (!hit) throw new Error(`relation role ${k} not configured`);
      R[k] = hit;
    }
    const addSource = config.addReferenced.find((a) => a.action === "Add Source" && a.sourceType === typeId.Source && a.destinationType === typeId.Evidence);
    out.resolved = { typeId, R: Object.fromEntries(Object.entries(R).map(([k, v]) => [k, `${v.id} ${v.label}/${v.complement}`])), addSource: Boolean(addSource) };
    const relIds = config.rels.map((r) => r.id);

    // ---- settings ----
    await step("flagsBefore", () => readPersonalFlags(page));
    await step("storedRelationsToggle", () => enableStoredRelationsUI(page));
    await step("flagsAfter", () => readPersonalFlags(page));

    const state = readState();
    const run = (state.runs?.length || 0) + 1;
    const runRec = { run, startedAt: new Date().toISOString(), nodes: {}, canvases: {} };
    out.run = run;

    // ---- hub page ----
    const hubUid = (await uidOf(page, HUB_TITLE)) || (await createPage(page, HUB_TITLE));
    runRec.hubUid = hubUid;

    // ---- node pages (Source first so evidence titles can reference it) ----
    const groupsUsed = [...new Set(FIXTURES.map((f) => f.group))].filter((g) => nodeGroups()[g]);
    const N = {}; // `${group}.${key}` -> {uid,title,type}
    await step("nodePages", async () => {
      for (const g of groupsUsed) {
        const defs = [...nodeGroups()[g]].sort((a, b) => (a[1] === "Source" ? -1 : 0) - (b[1] === "Source" ? -1 : 0));
        for (const [k, type, desc, , , srcKey] of defs) {
          const title = nodeTitle(type, nodeLabel(g, desc, run), srcKey ? N[`${g}.${srcKey}`]?.title : undefined);
          const uid = await createPage(page, title);
          N[`${g}.${k}`] = { uid, title, type, nodeTypeId: typeId[type] };
        }
      }
      runRec.nodes = N;
      return Object.keys(N).length;
    });

    // ---- canvas pages ----
    const C = {};
    await step("canvasPages", async () => {
      for (const fx of FIXTURES) C[fx.key] = { title: canvasTitle(fx, run), uid: await createPage(page, canvasTitle(fx, run)) };
      runRec.canvases = C;
      return C;
    });

    const nodeShapesFor = (fx) => (nodeGroups()[fx.group] || []).filter((d) => d[3] !== undefined).map(([k, , , x, y]) => {
      const n = N[`${fx.group}.${k}`];
      return { id: `shape:${k}`, type: "discourse-node", x, y, props: { uid: n.uid, title: n.title, nodeTypeId: n.nodeTypeId, w: 220, h: 90 } };
    });
    const creatableArrows = (fx) => (fx.arrows || []).filter((a) => ["rel", "arrow", "addsrc"].includes(a.kind)).map((a) => {
      const type = a.kind === "rel" ? R[a.rel].id : a.kind === "addsrc" ? "Add Source" : "arrow";
      const text = a.kind === "rel" ? (a.reverse ? R[a.rel].complement : R[a.rel].label) : a.kind === "addsrc" ? "for" : "";
      return { id: `shape:${a.id}`, type, from: `shape:${a.from}`, to: `shape:${a.to}`, props: { ...(a.kind === "arrow" ? {} : { text }), bend: a.bend || 0, ...(a.arrowheadStart ? { arrowheadStart: a.arrowheadStart } : {}), start: { x: 0, y: 0 }, end: { x: 10, y: 10 } } };
    });

    // ---- build canvases in the main editor ----
    for (const fx of FIXTURES.filter((f) => !f.copyOf && !f.injectOnly)) {
      await step(`build:${fx.key}`, async () => {
        const { uid, title } = C[fx.key];
        await openPage(page, uid);
        if (!(await waitEditor(page, title))) throw new Error("editor not ready");
        await closeRoamDialogs(page);
        const nodes = nodeShapesFor(fx);
        const arrows = creatableArrows(fx);
        if (arrows.some((a) => a.type === "Add Source") && !addSource) throw new Error("Add Source action missing");
        await page.evaluate(({ nodes, arrows }) => {
          const ed = window.__eng1955Ed();
          ed.createShapes(nodes);
          const bp = (t) => ({ terminal: t, normalizedAnchor: { x: 0.5, y: 0.5 }, isExact: false, isPrecise: false });
          for (const a of arrows) {
            ed.createShapes([{ id: a.id, type: a.type, x: 0, y: 0, props: a.props }]);
            ed.createBindings([{ type: a.type, fromId: a.id, toId: a.from, props: bp("start") }, { type: a.type, fromId: a.id, toId: a.to, props: bp("end") }]);
          }
          ed.zoomToFit();
          return true;
        }, { nodes, arrows });
        const want = [...nodes, ...arrows].map((s) => s.id);
        for (let i = 0; i < 40; i += 1) {
          await sleep(page, 500);
          const s = store(await readCanvasProps(page, uid)) || {};
          if (want.every((id) => s[id])) return { saved: want.length };
        }
        throw new Error("snapshot not saved to page props");
      });
    }
    await openPage(page, hubUid);
    await sleep(page, 2500);

    // ---- post-process local snapshots ----
    const bindingsOf = (s, id) => Object.values(s).filter((r) => r.typeName === "binding" && r.fromId === id);
    const addArrowFrom = (s, template, { id, type, from, to, props }) => {
      const t = clone(template);
      s[id] = { ...t, id, type, props: { ...t.props, ...props } };
      for (const b of bindingsOf(s, template.id)) {
        const nb = clone(b);
        nb.id = rid("binding");
        nb.type = type;
        nb.fromId = id;
        nb.toId = nb.props.terminal === "start" ? from : to;
        s[nb.id] = nb;
      }
    };
    const toCurrent = (props) => {
      const s = store(props);
      const converted = new Set();
      for (const r of Object.values(s)) {
        if (r.typeName === "shape" && relIds.includes(r.type)) { r.props.relationTypeId = r.type; r.type = DR; converted.add(r.id); }
      }
      for (const r of Object.values(s)) if (r.typeName === "binding" && converted.has(r.fromId)) r.type = DR;
      const seqs = qb(props).tldraw.schema.sequences;
      seqs[SEQ] = 6;
      if (seqs[`com.tldraw.shape.${DR}`] === undefined) seqs[`com.tldraw.shape.${DR}`] = 0;
      if (seqs[`com.tldraw.binding.${DR}`] === undefined) seqs[`com.tldraw.binding.${DR}`] = 0;
      for (const id of relIds) { delete seqs[`com.tldraw.shape.${id}`]; delete seqs[`com.tldraw.binding.${id}`]; }
      return converted.size;
    };
    const finalize = (props) => { qb(props).stateId = rid("seed").slice(5); return props; };

    const P = {};
    await step("postProcess", async () => {
      const res = {};
      for (const fx of FIXTURES.filter((f) => !f.copyOf && !f.injectOnly)) {
        const props = await readCanvasProps(page, C[fx.key].uid);
        const s = store(props);
        const seqs = qb(props).tldraw.schema.sequences;
        res[fx.key] = { seqBefore: seqs[SEQ] };
        for (const a of (fx.arrows || []).filter((x) => x.kind === "legacyUnknown")) {
          const tmpl = Object.values(s).find((r) => r.typeName === "shape" && relIds.includes(r.type));
          addArrowFrom(s, tmpl, { id: `shape:${a.id}`, type: a.type, from: `shape:${a.from}`, to: `shape:${a.to}`, props: { text: a.text, bend: a.bend || 0 } });
          if (a.schemaEntry !== false) { seqs[`com.tldraw.shape.${a.type}`] = 0; seqs[`com.tldraw.binding.${a.type}`] = 0; }
        }
        if (fx.mode === "current") {
          res[fx.key].converted = toCurrent(props);
