        const ns = { ...keep };
        for (const [k, type, fuid, desc, x, y] of fx.foreignNodes) {
          ns[`shape:${k}`] = { ...clone(nodeT), id: `shape:${k}`, x, y, props: { ...clone(nodeT.props), uid: fuid, title: nodeTitle(type, `ENG-1955 fx ${desc}`), nodeTypeId: typeId[type] } };
        }
        for (const [id, r] of Object.entries(s)) if (r.typeName === "shape" && r.id === arrowT.id) ns[id] = r;
        for (const b of bindingsOf(s, arrowT.id)) ns[b.id] = b;
        for (const a of fx.arrows) addArrowFrom(ns, arrowT, { id: `shape:${a.id}`, type: DR, from: `shape:${a.from}`, to: `shape:${a.to}`, props: { text: R[a.rel].label, relationTypeId: R[a.rel].id } });
        delete ns[arrowT.id];
        for (const b of Object.values(ns)) if (b.typeName === "binding" && b.fromId === arrowT.id) delete ns[b.id];
        qb(props).tldraw.store = ns;
        P[fx.key] = finalize(props);
        await writeCanvasProps(page, C[fx.key].uid, props);
      }
      // Identical copies.
      for (const fx of FIXTURES.filter((f) => f.copyOf)) {
        const props = finalize(clone(P[fx.copyOf]));
        P[fx.key] = props;
        await writeCanvasProps(page, C[fx.key].uid, props);
      }
      return res;
    });
    await sleep(page, 1500);

    // ---- cloud rooms (main build) ----
    for (const fx of FIXTURES.filter((f) => f.mode === "cloud")) {
      await step(`cloud:${fx.key}`, async () => {
        const { uid, title } = C[fx.key];
        const n = Object.values(store(P[fx.key])).filter((r) => r.typeName === "shape").length;
        await openPage(page, uid);
        if (!(await waitEditor(page, title, n))) throw new Error("local editor not ready");
        await closeRoamDialogs(page);
        await sleep(page, 1500);
        if (!(await switchToCloud(page, n))) throw new Error("cloud switch did not complete");
        await sleep(page, 15000);
        const recs = await editorRecords(page);
        const dump = { fixture: fx.key, pageUid: uid, build: "main", capturedAt: new Date().toISOString(), cloudIcon: await cloudIcon(page), ...summarizeRecords(recs) };
        writeDump(`${fx.key}-before.json`, dump);
        await page.evaluate(() => { window.__eng1955Ed().zoomToFit(); return true; });
        await sleep(page, 800);
        await page.screenshot({ path: path.join(outDir, `${fx.key}-main-cloud.png`) });
        return { cloudIcon: dump.cloudIcon, shapes: dump.shapes.length, bindings: dump.bindings.length };
      });
    }
    await openPage(page, hubUid);
    await sleep(page, 2000);

    // ---- stored (Roam) relations ----
    await step("storedRelations", async () => {
      const ourUids = Object.values(N).map((n) => n.uid);
      const before = await storedRelationsFor(page, ourUids);
      const created = [];
      for (const fx of FIXTURES.filter((f) => f.stored)) {
        for (const [from, role, to] of fx.stored) {
          const s = N[`${fx.group}.${from}`].uid; const d = N[`${fx.group}.${to}`].uid;
          if ([...before, ...created].some((r) => r.sourceUid === s && r.destinationUid === d && r.hasSchema === R[role].id)) continue;
          const uid = await createStoredRelation(page, { sourceUid: s, destinationUid: d, hasSchema: R[role].id });
          created.push({ uid, sourceUid: s, destinationUid: d, hasSchema: R[role].id, fixture: fx.key, label: `${from} ${R[role].label} ${to}` });
        }
      }
      await sleep(page, 1500);
      const after = await storedRelationsFor(page, ourUids);
      runRec.storedRelations = created;
      return { preexistingForOurNodes: before.length, created: created.length, totalAfter: after.length };
    });

    // ---- verify every fixture from page props (cloud: from the dumps above) ----
    await step("verify", async () => {
      const v = {};
      for (const fx of FIXTURES) {
        const props = await readCanvasProps(page, C[fx.key].uid);
        const q = qb(props) || {};
        const sum = summarizeRecords(q.tldraw?.store || {});
        v[fx.key] = {
          syncMode: q.canvasSyncMode ?? "local", seq: q.tldraw?.schema?.sequences?.[SEQ],
          shapes: sum.shapes.map((s) => `${s.id}:${s.type}${s.relationTypeId ? `/${s.relationTypeId}` : ""}${s.uid ? `@${s.uid}` : ""}${s.text !== undefined && !s.uid ? ` "${s.text}"` : ""}${s.bend ? ` bend=${s.bend}` : ""}${s.arrowheadStart && s.arrowheadStart !== "none" ? ` start=${s.arrowheadStart}` : ""}`),
          bindings: [...new Set(sum.bindings.map((b) => b.type))],
          bindingCount: sum.bindings.length,
        };
        if (fx.key === "F3") writeDump("F3-local-before.json", { fixture: "F3", pageUid: C.F3.uid, source: "page props (local)", capturedAt: new Date().toISOString(), schemaSeq: v.F3.seq, ...sum });
      }
      writeDump("verify.json", v);
      return v;
    });

    // ---- hub ----
    await step("hub", async () => {
      await clearChildren(page, hubUid);
      const tree = buildHub({ run, C, N, R, typeId, storedCreated: runRec.storedRelations });
      await createTree(page, hubUid, tree);
      const count = await page.evaluate((u) => window.roamAlphaAPI.q(`[:find (count ?b) . :in $ ?p :where [?pg :block/uid ?p] [?b :block/page ?pg]]`, u), hubUid);
      return { blocks: count };
    });

    runRec.finishedAt = new Date().toISOString();
    state.runs = [...(state.runs || []), runRec];
    state.hub = { title: HUB_TITLE, uid: hubUid };
    writeState(state);
    out.errors = errorsIn(logs).slice(0, 25);
    flush();
    return { run, hubUid, canvases: Object.fromEntries(Object.entries(C).map(([k, v]) => [k, v.title])) };
  },
};

