            else {
              // No known relation on this canvas to copy: borrow X1's relation record as the template.
              const x1 = store(P["F9-X1"] || (await readCanvasProps(page, C["F9-X1"].uid)));
              const t = Object.values(x1).find((r) => r.typeName === "shape" && (r.type === DR || relIds.includes(r.type)));
              const tb = bindingsOf(x1, t.id);
              const tmp = clone(t); tmp.type = DR; tmp.props.relationTypeId = a.relationTypeId;
              s[tmp.id] = tmp; for (const b of tb) s[b.id] = clone(b);
              addArrowFrom(s, tmp, { id: `shape:${a.id}`, type: DR, from: `shape:${a.from}`, to: `shape:${a.to}`, props: { text: a.text, relationTypeId: a.relationTypeId, bend: a.bend || 0 } });
              delete s[tmp.id]; for (const b of Object.values(s)) if (b.typeName === "binding" && b.fromId === tmp.id) delete s[b.id];
            }
          }
        }
        P[fx.key] = finalize(props);
        await writeCanvasProps(page, C[fx.key].uid, props);
      }
      // F9-X4: injected only, built from X1's (converted) snapshot.
      for (const fx of FIXTURES.filter((f) => f.injectOnly)) {
        const props = clone(P[fx.templateFrom]);
        const s = store(props);
        const nodeT = Object.values(s).find((r) => r.typeName === "shape" && r.type === "discourse-node");
        const arrowT = Object.values(s).find((r) => r.typeName === "shape" && r.type === DR);
        const keep = Object.fromEntries(Object.entries(s).filter(([, r]) => r.typeName !== "shape" && r.typeName !== "binding"));
        const ns = { ...keep };
        for (const [k, type, fuid, desc, x, y] of fx.foreignNodes) {
          ns[`shape:${k}`] = { ...clone(nodeT), id: `shape:${k}`, x, y, props: { ...clone(nodeT.props), uid: fuid, title: nodeTitle(type, `ENG-1955 fx ${desc}`), nodeTypeId: typeId[type] } };
        }
        for (const [id, r] of Object.entries(s)) if (r.typeName === "shape" && r.id === arrowT.id) ns[id] = r;
        for (const b of bindingsOf(s, arrowT.id)) ns[b.id] = b;
        for (const a of fx.arrows) addArrowFrom(ns, arrowT, { id: `shape:${a.id}`, type: DR, from: `shape:${a.from}`, to: `shape:${a.to}`, props: { text: R[a.rel].label, relationTypeId: R[a.rel].id } });
