          text: button.textContent?.trim() || "",
          ariaLabel: button.getAttribute("aria-label"),
          title: button.getAttribute("title"),
          className: button.className,
        }))
        .slice(0, 50),
      visibleText: document.body.innerText
        .split("\n")
        .map((line) => line.trim())
        .filter(Boolean)
        .slice(0, 200),
    }))
    .catch(() => null);

