// Hub page content: Michael's PR #1167 checklist (case wording verbatim) mapped to empty fixture canvases.
import { W, SEED_DIR, ENG_DIR } from "./lib.mjs";

export const HUB_TITLE = "ENG-1955 Test Plan";
const PROFILE = "/Users/trang.doan/Desktop/code/discourse-graph/local/roam-playwright/profiles/playwright-1";
const loader = (b) => `\`cd ${W} && DG_ROAM_PLAYWRIGHT_PROFILE_DIR_1=${PROFILE} pnpm --filter roam playwright:load-extension -- --slot 1 --skip-build --registration-name dist --headed --keep-open --dist ${ENG_DIR}/builds/${b}/dist\``;
const B = { main: "Build: **main**", nofix: "Build: **nofix**", branch: "Build: **branch**" };
const MAIN_FIRST = "Draw this with the MAIN build first (Builds: main loader command, or point ~/roam-ext-dev at builds/main/dist), then switch to the build the case names.";

// C: fixture key -> canvas title; N: "group.key" -> node page title.
export const buildHub = ({ run, C, N, R }) => {
  const L = (k) => `[[${C[k]}]]`;
  const n = (g, k) => `[[${N[`${g}.${k}`]}]]`;
  const tc = (text, fixture, build, steps, expected) => ({
    text: `{{[[TODO]]}} ${text}`,
    children: [{ text: `Fixture: ${fixture}` }, { text: build }, { text: "Steps", children: steps.map((t) => ({ text: t })) }, { text: `Expected: ${expected}` }],
  });
  const na = (text, reason) => ({ text: `{{[[TODO]]}} ${text}`, children: [{ text: `**N/A** - ${reason}` }] });
  const sec = (title, children, notes = []) => ({ text: `### ${title}`, children: [...notes.map((t) => ({ text: t })), ...children] });
  const draw = (title, lines) => ({ text: `**${title}**`, children: lines.map((t) => ({ text: t })) });
  const naImport = "there is no canvas import feature; canvas data only moves between graphs by copy/paste, which is covered in Cross-Graph / Missing Schema Cases (F9).";
  const sup = R.SUP.label; const supC = R.SUP.complement; const inf = R.INF.label; const infC = R.INF.complement;
  const TMP = "The seed does not change relation configuration; creating and deleting the temporary relation type is a tester step.";

  const f1Draw = (k, g) => [
    MAIN_FIRST,
    `Open ${L(k)} (Auto canvas relations OFF) and add: ${n(g, "E1")}, ${n(g, "E2")}, ${n(g, "C1")}, ${n(g, "C2")}, ${n(g, "Q1")}, ${n(g, "S1")}.`,
    `a1: ${sup} evidence one -> claim one (relation tool).`,
    `a2: ${sup} drawn from claim two -> evidence two (shows "${supC}", complement).`,
    `a3: ${inf} claim one -> question one; drag its midpoint to curve it and set a start arrowhead in the style panel.`,
    `a4: ${R.OPP.label} evidence two -> claim one, curved the other way.`,
    `a5: ${R.COR.label} evidence one -> claim one (second relation type on the same pair).`,
    "a6: plain tldraw arrow claim two -> question one (arrow tool).",
    "a7: Add Source from source one -> evidence one (Add Source in the discourse tool panel).",
    "Wait a few seconds for it to save; screenshot it and run the inspect snippet as the before-record.",
  ];

  const top = [
    { text: `**Seed r${run}** - fixture canvases are EMPTY pages; each case says what to draw and with which build. The fx node pages and the Roam relations named per case already exist. Nothing below has been executed.` },
    { text: "Add nodes to a canvas with the discourse tool (pick the node type, click the canvas, choose the existing page) or by dragging the page in from the sidebar." },
    {
      text: "**What the PR changes**",
      children: [
        { text: "Canvas relation arrows move from shape `type` = relation uid (bindings typed the same) to one `discourse-relation` shape type with the relation in `props.relationTypeId`." },
        { text: "Local canvases migrate on load (migration v6 MigrateRelationTypeToDiscourseRelation, sequence com.roam-research.discourse-graphs); cloud rooms are never migrated, so the branch registers the legacy uid-typed utils on the cloud path only." },
        { text: "Arrows with an unknown relationTypeId render with their stored text and skip Roam persistence instead of breaking the canvas." },
      ],
    },
    {
      text: "**Builds** (local/roam-playwright/eng1955/builds/<x>/dist, gitignored)",
      children: [
        { text: "main - origin/main 96eaf97b - pre-migration; draws uid-typed arrows; the ONLY build allowed on F2A", children: [{ text: `Playwright: ${loader("main")}` }] },
        { text: "nofix - 7fd5a170 - this PR without the cloud fix", children: [{ text: `Playwright: ${loader("nofix")}` }] },
        { text: "branch - f7d9f4a3 (PR HEAD watcher build; contains LegacyRelationBindingUtil)", children: [{ text: `Playwright: ${loader("branch")}` }] },
        { text: "Normal Chrome instead of Playwright: point ~/roam-ext-dev at builds/<x>/dist and reload the developer extension. ~/roam-ext-dev is shared across worktree sessions, so check its target first." },
        { text: "The loader reports the page error \"Client does not have permission to change settings on extensions set by the admin\"; it is harmless." },
      ],
    },
    {
      text: "**Re-seed**",
      children: [
        { text: `\`zsh ${SEED_DIR}/seed-all.sh\` - reuses the r${run} pages, creates missing node pages and Roam relations, rewrites this page. \`SEED_NEW_RUN=1 zsh ${SEED_DIR}/seed-all.sh\` makes a fresh r${run + 1} set (new canvas pages = new cloud rooms).` },
        { text: "Cloud rooms cannot be deleted or reset, and a canvas you drew on is no longer empty; use a fresh run for clean ones." },
      ],
    },
    {
      text: "**Settings**",
      children: [
        { text: "Enable stored relations: turned ON by the seed (Personal settings). It is an extension setting, so confirm it is ON in the build/browser you test with." },
        { text: "Auto canvas relations: personal setting (Personal settings > Auto canvas relations). Keep it OFF while drawing fixtures; cases say when to turn it ON." },
      ],
    },
    { text: "**Two-window testing**: use two normal Chrome windows on the same canvas page. Playwright runs one browser context, so there use the main window plus the right sidebar instead." },
    { text: "**Analytics**: DevTools > Network, filter `posthog` (or `/e/`). The event `Canvas: Relation Created` should carry `relationType` = the relation uid and `toolType`." },
    {
      text: "**Inspect canvas records** (paste in the DevTools console with the canvas open; lists shape and binding types)",
      children: [{ text: "```javascript\n(() => { const el = document.querySelector('.roam-article .roamjs-tldraw-canvas-container .tl-canvas'); let f = el[Object.keys(el).find((k) => k.startsWith('__reactFiber$'))]; let ed; for (let i = 0; f && i < 400 && !ed; i += 1, f = f.return) { const p = f.memoizedProps; ed = [p?.editor, p?.value].find((v) => v?.store && v?.getCurrentPageShapes); } const recs = ed.store.allRecords(); console.table(recs.filter((r) => r.typeName === 'shape').map((s) => ({ id: s.id, type: s.type, relationTypeId: s.props.relationTypeId, text: s.props.text ?? s.props.title }))); console.table(recs.filter((r) => r.typeName === 'binding').map((b) => ({ id: b.id, type: b.type, fromId: b.fromId, toId: b.toId, terminal: b.props.terminal }))); })();\n```" }],
    },
    {
      text: "**Fixture drawings** (do these before the cases that use them)",
      children: [
        draw("F1a / F1b - pre-migration local canvas (identical; F1a stays the untouched reference, open it only with main afterwards)", [
          ...f1Draw("F1a", "F1"), `Repeat the same drawing on ${L("F1b")}.`,
          `a8 (old relation id no longer in settings): with main, create a temporary Evidence -> Claim relation type, draw it evidence two -> claim two on F1a and F1b, then delete that relation type. ${TMP}`,
        ]),
        draw("F2A / F2B - pre-migration cloud rooms", [
          ...f1Draw("F2A", "F2"), `Repeat on ${L("F2B")}.`,
          "Still with main, on each: main menu > (Beta) Use cloud canvas > Move to cloud sync. Run the inspect snippet on each and save the output.",
          "From now on open F2A only with the main build.",
        ]),
        draw("F3 - local canvas to convert", [MAIN_FIRST, `Open ${L("F3")} (Auto canvas relations OFF), add ${n("F3", "E1")}, ${n("F3", "C1")}, ${n("F3", "Q1")}.`, `Draw ${sup} evidence one -> claim one and ${inf} claim one -> question one. Roam already has those two relations plus evidence one ${R.OPP.label} claim one (not drawn).`, "Do not switch to cloud yet; run the inspect snippet and save it."]),
        draw("F4 - new relation creation", [`Branch build. Open ${L("F4")} and add ${n("F4", "E1")}, ${n("F4", "C1")}, ${n("F4", "C2")}, ${n("F4", "Q1")}, ${n("F4", "Q2")}, ${n("F4", "S1")}, ${n("F4", "E2")}, ${n("F4", "C3")}.`, "Draw a plain tldraw arrow evidence two -> claim three. No Roam relations exist between these nodes."]),
        draw("F5 - relation editing", [`Branch build. Open ${L("F5")} and add ${n("F5", "E1")}, ${n("F5", "C1")}, ${n("F5", "C2")}, ${n("F5", "Q1")}.`, `Draw ${sup} evidence one -> claim one and ${inf} claim one -> question one (Roam already has both).`]),
        draw("F6a - auto canvas relations", [`Branch build. Open ${L("F6a")} and add only ${n("F6a", "C1")}; the other nodes stay off until the cases.`, `Roam has: evidence one ${sup} and ${R.OPP.label} claim one; claim one ${inf} question one; claim one ${R.OPPCC.label} claim two and claim two ${R.OPPCC.label} claim one.`]),
        draw("F6b / F6c - legacy arrow de-dupe", [MAIN_FIRST, `Open ${L("F6b")}, add ${n("F6bc", "E1")} and ${n("F6bc", "C1")}, draw ${sup} evidence one -> claim one.`, `Repeat on ${L("F6c")}, then switch F6c to cloud with main (main menu > (Beta) Use cloud canvas > Move to cloud sync).`, `Roam has evidence one ${sup} and ${R.COR.label} claim one.`]),
        draw("F7 - Roam persistence", [`Branch build, stored relations ON. Open ${L("F7")} and add ${n("F7", "E1")}, ${n("F7", "C1")}, ${n("F7", "C2")}, ${n("F7", "Q1")}, ${n("F7", "Q2")}, ${n("F7", "S1")}, ${n("F7", "E2")}, ${n("F7", "CD")}, ${n("F7", "CR")}, ${n("F7", "Q3")}.`, `Draw ${sup} evidence two -> claim DELETE ME and ${inf} claim RENAME ME -> question three (Roam already has both).`]),
        draw("F8 - export", [`Branch build. Open ${L("F8")}, add ${n("F8", "E1")}, ${n("F8", "C1")}, ${n("F8", "Q1")}, ${n("F8", "S1")}.`, `Draw ${sup} evidence one -> claim one, ${inf} claim one -> question one, Add Source source one -> evidence one.`, `Unknown relationTypeId arrow: create a temporary Evidence -> Question relation type, draw it evidence one -> question one with the branch build, then delete that relation type. ${TMP}`]),
        draw("F9 - cross-graph simulation", [
          `X1 (branch): open ${L("F9-X1")}, add ${n("X1", "E1")}, ${n("X1", "C1")}, draw ${sup} evidence one -> claim one.`,
          `X2 (branch): open ${L("F9-X2")}, add ${n("X2", "E1")}, ${n("X2", "C1")}, draw a temporary Evidence -> Claim relation type, then delete that type (current-format arrow whose relationTypeId is missing). ${TMP}`,
          `X3: ${MAIN_FIRST} Open ${L("F9-X3")}, add ${n("X3", "E1")}, ${n("X3", "C1")}, draw a temporary relation type with main, delete the type, then open with branch (pre-v6 arrow typed by a uid this graph no longer has).`,
          `X4: open ${L("F9-X4")} and paste two nodes plus a relation copied from a canvas in another graph (their uids do not exist here). Without a second graph, skip X4 and note it.`,
        ]),
        draw("F10 - regression smoke", [`Branch build. Open ${L("F10")}, add ${n("F10", "E1")}, ${n("F10", "C1")}, ${n("F10", "C2")}; draw ${sup} evidence one -> claim one and a plain arrow claim one -> claim two.`]),
      ],
    },
  ];

  const f1 = "After drawing F1a/F1b with main (Fixture drawings), open F1b with the branch build. Leave F1a untouched; open it only with main.";
  const sections = [
    sec("Baseline Setup", [
      tc("Test in a graph with at least two discourse node types and at least two relation types.", "dev graph config (Claim, Evidence, Question, Source; Supports, opposes, Corroborates, Informs)", B.branch, ["Nothing to do; the seed resolved these types at runtime."], "Met by the dev graph."),
      tc("Include relation types with complements, for example `Supports` / `Supported By`.", `${L("F1b")} arrow a2`, B.branch, [f1, "Check a2 (claim two -> evidence two)."], `a2 shows "${supC}".`),
      tc("Include two distinct relation types that can connect the same source and target node types.", `Evidence -> Claim has ${sup}, ${R.OPP.label}, ${R.COR.label}; used in ${L("F1b")} (a1 + a5), ${L("F4")}, ${L("F6a")}`, B.branch, ["Nothing to do."], "Met."),
      tc("Test with both `auto canvas relations` enabled and disabled.", `ON for ${L("F3")} (Cloudflare Sync case 8) and Auto Canvas Relations (F6a/F6b/F6c); OFF elsewhere`, B.branch, ["Toggle Personal settings > Auto canvas relations as each case says."], "Each case states its setting."),
      tc("Test both local canvas mode and Cloudflare sync mode.", `local: F1b, F3, F4, F5, F7, F8, F9, F10; cloud: ${L("F2B")}, ${L("F6c")}, F3 after switching`, B.branch, ["Nothing to do."], "Both modes covered."),
    ]),
    sec("Existing Canvas Migration", [
      tc("Open an existing pre-migration canvas with relation arrows whose shape `type` is a relation id.", L("F1b"), B.branch, [f1], "Canvas opens."),
      tc("Confirm the canvas loads without an upgrade/error screen.", L("F1b"), B.branch, [f1], "No upgrade dialog, no error screen."),
      tc("Confirm old relation arrows render with correct label, color, endpoints, bend, and arrowhead.", `${L("F1b")} vs ${L("F1a")} (main screenshot)`, B.branch, [f1, "Compare a1-a5 with the main screenshot."], "Same labels, colors, endpoints, bends and arrowheads."),
      tc("Confirm old relation bindings still attach to the correct source and target nodes.", L("F1b"), B.branch, [f1, "Move each node; run the inspect snippet."], "Arrows follow their nodes; each relation has start and end bindings to the original nodes."),
      tc("Confirm migrated relation shapes now behave as `discourse-relation` with `props.relationTypeId`.", L("F1b"), B.branch, [f1, "Run the inspect snippet."], `a1-a5 are discourse-relation with relationTypeId = their old uid (e.g. ${R.SUP.id}); their bindings are discourse-relation.`),
