// ENG-1955 fixture seed (reduced scope): fx node pages, Roam relations, hub page. Canvas pages are created only by
// the hub's [[Canvas/...]] links and stay empty. SEED_NEW_RUN=1 starts a fresh run tag instead of reusing the current one.
import fs from "node:fs";
import path from "node:path";
import {
  installEditorFinder, closeRoamDialogs, uidOf, readState, writeState, writeDump, sleep, readCanvasProps, writeCanvasProps,
  readPersonalFlags, enableStoredRelationsUI, readConfig, createPage, createStoredRelation, storedRelationsFor, createTree,
  clearChildren, allLogs, errorsIn,
} from "./lib.mjs";
import { ROLE, FIXTURES, nodeGroups, canvasTitle, nodeLabel, nodeTitle } from "./fixtures.mjs";
import { buildHub, HUB_TITLE } from "./hub.mjs";

export default {
  async ready({ page }) {
    await closeRoamDialogs(page);
    return page.evaluate(() => Boolean(window.roamAlphaAPI && window.roamjs?.extension?.queryBuilder));
  },
  async run({ page, outDir }) {
    const logs = allLogs(page);
    await installEditorFinder(page);
    const out = { steps: {} };
    const flush = () => fs.writeFileSync(path.join(outDir, "seed-result.json"), JSON.stringify(out, null, 2));
    const step = async (name, fn) => {
      try { out.steps[name] = (await fn()) ?? "ok"; } catch (e) { out.steps[name] = { error: String(e?.stack || e).slice(0, 800) }; flush(); throw e; }
      flush();
      return out.steps[name];
    };

    const config = await readConfig(page);
    const typeId = Object.fromEntries(["Claim", "Evidence", "Question", "Source"].map((t) => [t, config.nodes.find((x) => x.text === t)?.type]));
    const R = {};
    for (const [k, r] of Object.entries(ROLE)) {
      R[k] = config.rels.find((x) => x.label === r.label && x.source === typeId[r.source] && x.destination === typeId[r.destination]);
      if (!R[k]) throw new Error(`relation role ${k} not configured`);
    }
    out.resolved = { typeId, R: Object.fromEntries(Object.entries(R).map(([k, v]) => [k, `${v.id} ${v.label}/${v.complement}`])), addSource: config.addReferenced.some((a) => a.action === "Add Source") };

    await step("flagsBefore", () => readPersonalFlags(page));
    if (!out.steps.flagsBefore.storedRelations) await step("storedRelationsToggle", () => enableStoredRelationsUI(page));
    await step("flagsAfter", () => readPersonalFlags(page));

    const state = readState();
    let run = state.currentRun || 1;
    if (process.env.SEED_NEW_RUN === "1") run = Math.max(state.nextRun || 1, run + 1);
    state.currentRun = run;
    state.nextRun = Math.max(state.nextRun || 1, run + 1);
    writeState(state);
    out.run = run;

    // Node pages: reuse by title, create only when missing (Source first so evidence titles can reference it).
    const N = {};
    await step("nodePages", async () => {
      let created = 0;
      for (const g of [...new Set(FIXTURES.map((f) => f.group))].filter((x) => nodeGroups()[x])) {
        const defs = [...nodeGroups()[g]].sort((a, b) => (a[1] === "Source" ? -1 : 0) - (b[1] === "Source" ? -1 : 0));
        for (const [k, type, desc, , , srcKey] of defs) {
          const title = nodeTitle(type, nodeLabel(g, desc, run), srcKey ? N[`${g}.${srcKey}`]?.title : undefined);
          let uid = await uidOf(page, title);
          if (!uid) { uid = await createPage(page, title); created += 1; }
          N[`${g}.${k}`] = { uid, title, type };
        }
      }
      return { total: Object.keys(N).length, created };
    });

    // Canvas pages must hold no tldraw data; strip any left by the earlier (aborted) drawing seed.
    const C = Object.fromEntries(FIXTURES.map((fx) => [fx.key, canvasTitle(fx, run)]));
    await step("emptyCanvases", async () => {
      const res = {};
      for (const [k, title] of Object.entries(C)) {
        const uid = await uidOf(page, title);
        if (!uid) { res[k] = "absent (hub link creates it)"; continue; }
        const props = await readCanvasProps(page, uid);
        const qb = props["roamjs-query-builder"];
        if (qb && (qb.tldraw || qb.canvasSyncMode)) {
          const { tldraw, stateId, canvasSyncMode, canvasSyncMigrationState, ...rest } = qb;
          const next = { ...props };
          if (Object.keys(rest).length) next["roamjs-query-builder"] = rest; else delete next["roamjs-query-builder"];
          await writeCanvasProps(page, uid, next);
          res[k] = `stripped tldraw data (${Object.keys(tldraw?.store || {}).length} records)`;
        } else res[k] = "empty";
      }
      return res;
    });

    await step("storedRelations", async () => {
      const ourUids = Object.values(N).map((x) => x.uid);
      const existing = await storedRelationsFor(page, ourUids);
      const created = [];
      for (const fx of FIXTURES.filter((f) => f.stored)) {
        for (const [from, role, to] of fx.stored) {
          const s = N[`${fx.group}.${from}`].uid; const d = N[`${fx.group}.${to}`].uid;
          if ([...existing, ...created].some((r) => r.sourceUid === s && r.destinationUid === d && r.hasSchema === R[role].id)) continue;
          const uid = await createStoredRelation(page, { sourceUid: s, destinationUid: d, hasSchema: R[role].id });
          created.push({ uid, sourceUid: s, destinationUid: d, hasSchema: R[role].id, fixture: fx.key, label: `${fx.group} ${from} ${R[role].label} ${to}` });
        }
      }
      await sleep(page, 1500);
      const after = await storedRelationsFor(page, ourUids);
      return { existingBefore: existing.length, created, totalAfter: after.length };
    });

    const hubUid = (await uidOf(page, HUB_TITLE)) || (await createPage(page, HUB_TITLE));
    await step("hub", async () => {
      const removed = await clearChildren(page, hubUid);
      const tree = buildHub({ run, C, N: Object.fromEntries(Object.entries(N).map(([k, v]) => [k, v.title])), R });
      await createTree(page, hubUid, tree);
      return { removed };
    });
    await sleep(page, 3000);

    await step("verify", async () => {
      const canvases = {};
      for (const [k, title] of Object.entries(C)) {
        const uid = await uidOf(page, title);
        const props = uid ? await readCanvasProps(page, uid) : null;
        canvases[k] = { title, uid, hasTldraw: Boolean(props?.["roamjs-query-builder"]?.tldraw) };
      }
      const refs = await page.evaluate((u) => window.roamAlphaAPI.q(`[:find [?t ...] :in $ ?p :where [?pg :block/uid ?p] [?b :block/page ?pg] [?b :block/refs ?r] [?r :node/title ?t]]`, u), hubUid);
      const wanted = [...Object.values(C), ...Object.values(N).map((x) => x.title)];
      const blocks = await page.evaluate((u) => window.roamAlphaAPI.q(`[:find (count ?b) . :in $ ?p :where [?pg :block/uid ?p] [?b :block/page ?pg]]`, u), hubUid);
      const todos = await page.evaluate((u) => window.roamAlphaAPI.q(`[:find (count ?b) . :in $ ?p :where [?pg :block/uid ?p] [?b :block/page ?pg] [?b :block/string ?s] [(clojure.string/starts-with? ?s "{{[[TODO]]}}")]]`, u), hubUid);
      const v = {
        hub: { title: HUB_TITLE, uid: hubUid, blocks, todos },
        canvases,
        missingCanvasPages: Object.entries(canvases).filter(([, c]) => !c.uid).map(([k]) => k),
        canvasesWithTldraw: Object.entries(canvases).filter(([, c]) => c.hasTldraw).map(([k]) => k),
        hubLinksUnresolved: wanted.filter((t) => !refs.includes(t)),
        nodePagesLinkedFromHub: Object.values(N).filter((x) => refs.includes(x.title)).length,
        nodePagesTotal: Object.keys(N).length,
      };
      writeDump("verify.json", v);
      return v;
    });

    state.runs = [...(state.runs || []).filter((r) => r.run !== run), { run, seededAt: new Date().toISOString(), hubUid, nodes: N, canvases: out.steps.verify.canvases, storedRelations: out.steps.storedRelations.created }];
    state.hub = { title: HUB_TITLE, uid: hubUid };
    writeState(state);
    out.errors = errorsIn(logs).slice(0, 20);
    flush();
    return { run, hub: HUB_TITLE, verify: out.steps.verify };
  },
};

